"""`cement-projection-v1` + `-v2`: a closed, line-oriented recognizer from raw input to a case key.

Contract: `.agent/decisions/m45-contract.md` §4. The text rules are explicit ASCII on purpose:
Python 3.12-3.15 ship four Unicode databases (UCD 15.0.0 -> 17.0.0), so `str.isspace`, `lower`
or NFKC would make one key depend on the interpreter. No regex runs on input, nothing is
evaluated, and `work` counts the characters, lines and entries the recognizer touches. v2 (p97)
differs in one rule: a label ends at the first ASCII colon OR full-width colon (U+FF1A), so forms
that label with U+FF1A (Japanese) get layouts; a v1 program keeps its ASCII-only meaning unchanged.
"""

from __future__ import annotations

import string
from dataclasses import dataclass
from typing import Literal, TypedDict, cast

from .errors import ValidationError
from .json_value import CanonicalJSON, JSONValue, canonicalize

__all__ = [
    "PROJECTION_ABI",
    "Layout",
    "Projection",
    "ProjectionProgram",
    "parse_program",
    "project",
    "structure",
]

PROJECTION_ABI = "cement-projection-v1"
PROJECTION_ABI_V2 = "cement-projection-v2"
# The label separators per ABI. v1 stays ASCII-only, so a promoted v1 program never widens.
_SEPARATORS = {PROJECTION_ABI: (":",), PROJECTION_ABI_V2: (":", "\uff1a")}
PROGRAM_MAX_BYTES = 64 * 1024
MAX_LAYOUTS = 1_000
MAX_ENTRIES = 256
MAX_KEEP = 32
MAX_FIELD = 128
MAX_LITERAL = 256

Reason = Literal["input", "text", "layout", "key"]

_FIELD_CHARS = frozenset(string.ascii_letters + string.digits + "_.-")
_LITERAL_FORBIDDEN = frozenset(
    [chr(code) for code in (*range(0x20), *range(0x7F, 0xA0))] + ["\u2028", "\u2029"]
)
# Input lines keep TAB: it is the one control character the grammar trims and partitions around.
_TEXT_FORBIDDEN = _LITERAL_FORBIDDEN - {"\t"}
_EDGE = " \t"
_ASCII_LOWER = str.maketrans(string.ascii_uppercase, string.ascii_lowercase)


@dataclass(frozen=True, slots=True)
class Layout:
    name: str
    title: str
    entries: tuple[tuple[str, str], ...]


@dataclass(frozen=True, slots=True)
class ProjectionProgram:
    text: str
    keep: tuple[str, ...]
    layouts: tuple[Layout, ...]
    canonical: CanonicalJSON
    program_hash: str


@dataclass(frozen=True, slots=True)
class Projection:
    matched: bool
    key: CanonicalJSON | None
    reason: Reason | None
    work: int


def _exact_keys(value: object, expected: set[str], label: str) -> dict[str, object]:
    if type(value) is not dict or set(value) != expected:
        raise ValidationError(f"{label} must be an object with keys {sorted(expected)!r}")
    return value


def _field(value: object, label: str) -> str:
    if (
        type(value) is not str
        or not 1 <= len(value) <= MAX_FIELD
        or any(char not in _FIELD_CHARS for char in value)
    ):
        raise ValidationError(f"{label} must be 1-{MAX_FIELD} ASCII letters, digits, '_', '.', '-'")
    return value


def _literal(value: object, label: str, *, separators: tuple[str, ...] = ()) -> str:
    if type(value) is not str or not 1 <= len(value) <= MAX_LITERAL:
        raise ValidationError(f"{label} must be a string of 1-{MAX_LITERAL} characters")
    if any(char in _LITERAL_FORBIDDEN or 0xD800 <= ord(char) <= 0xDFFF for char in value):
        raise ValidationError(f"{label} holds a control character or a lone surrogate")
    if value[0] in _EDGE or value[-1] in _EDGE:
        raise ValidationError(f"{label} must not start or end with an ASCII space or tab")
    for separator in separators:
        if separator in value:
            raise ValidationError(f"{label} must not contain {separator!r}")
    return value


def _entry(value: object, label: str, separators: tuple[str, ...]) -> tuple[str, str]:
    if type(value) is not dict or len(value) != 1 or next(iter(value)) not in {"label", "section"}:
        raise ValidationError(f"{label} must be exactly {{'label': K}} or {{'section': H}}")
    kind = next(iter(value))
    return kind, _literal(value[kind], f"{label} {kind}", separators=separators)


def parse_program(value: object) -> ProjectionProgram:
    """Validate one program object; every rule violation raises `ValidationError` naming it."""

    root = _exact_keys(value, {"abi", "text", "keep", "layouts"}, "projection program")
    if type(root["abi"]) is not str or root["abi"] not in _SEPARATORS:
        raise ValidationError(f"projection abi must be {PROJECTION_ABI!r} or {PROJECTION_ABI_V2!r}")
    separators = _SEPARATORS[str(root["abi"])]
    text = _field(root["text"], "projection text")
    raw_keep = root["keep"]
    if type(raw_keep) is not list or len(raw_keep) > MAX_KEEP:
        raise ValidationError(f"projection keep must be an array of at most {MAX_KEEP} fields")
    keep = tuple(_field(item, "projection keep field") for item in raw_keep)
    if list(keep) != sorted(set(keep)):
        raise ValidationError("projection keep fields must be sorted and unique")
    if text in keep:
        raise ValidationError("projection text field must not also be kept")
    raw_layouts = root["layouts"]
    if type(raw_layouts) is not list or not 1 <= len(raw_layouts) <= MAX_LAYOUTS:
        raise ValidationError(f"projection layouts must be an array of 1-{MAX_LAYOUTS}")
    layouts: list[Layout] = []
    seen: set[tuple[str, tuple[tuple[str, str], ...]]] = set()
    for index, raw_layout in enumerate(raw_layouts):
        layout = _exact_keys(raw_layout, {"name", "title", "entries"}, f"projection layout {index}")
        name = _literal(layout["name"], f"layout {index} name")
        title = _literal(layout["title"], f"layout {index} title")
        raw_entries = layout["entries"]
        if type(raw_entries) is not list or not 1 <= len(raw_entries) <= MAX_ENTRIES:
            raise ValidationError(f"layout {index} entries must be an array of 1-{MAX_ENTRIES}")
        entries = tuple(
            _entry(item, f"layout {index} entry {position}", separators)
            for position, item in enumerate(raw_entries)
        )
        identity = (title, entries)
        if identity in seen:
            raise ValidationError(f"layout {index} repeats an earlier layout's title + entries")
        seen.add(identity)
        layouts.append(Layout(name=name, title=title, entries=entries))
    canonical = canonicalize(value, max_bytes=PROGRAM_MAX_BYTES)
    return ProjectionProgram(
        text=text,
        keep=keep,
        layouts=tuple(layouts),
        canonical=canonical,
        program_hash=canonical.digest,
    )


def _label(line: str, separators: tuple[str, ...]) -> tuple[str, str] | None:
    cut = min((at for at in (line.find(s) for s in separators) if at >= 0), default=-1)
    if cut < 0:
        return None
    key = line[:cut].strip(_EDGE)
    if not key:
        return None
    return key, line[cut + 1 :]


def program_abi(program: ProjectionProgram) -> str:
    """The program's own ABI string (the field is inside its canonical bytes, already validated)."""

    root = program.canonical.value
    assert type(root) is dict  # noqa: S101 — narrowing only: parse_program built it from an object
    return str(root["abi"])


def _lines(text: str) -> list[str]:
    return text.replace("\r\n", "\n").replace("\r", "\n").split("\n")


def label_lines(program: ProjectionProgram, text: str) -> tuple[list[str], list[int]]:
    """The text's lines as the grammar splits them, and the indices of the lines that hold one of
    the program's label separators (structure lines; title and section bodies aside)."""

    lines = _lines(text)
    separators = _SEPARATORS[program_abi(program)]
    return lines, [i for i, line in enumerate(lines) if any(s in line for s in separators)]


def _structure(
    text: str, separators: tuple[str, ...] = (":",)
) -> tuple[tuple[str, tuple[tuple[str, str], ...]] | None, int]:
    work = len(text)
    lines: list[str] = []
    for raw in _lines(text):
        line = raw.rstrip(_EDGE)
        work += len(raw) + 1
        if any(char in _TEXT_FORBIDDEN for char in line):
            return None, work
        lines.append(line)
    blocks: list[list[str]] = [[]]
    for line in lines:
        work += 1
        if line:
            blocks[-1].append(line)
        elif blocks[-1]:
            blocks.append([])
    if not blocks[-1]:
        blocks.pop()
    if not blocks:
        return None, work
    title, *header = blocks[0]
    pairs: list[tuple[str, str]] = []
    for line in header:
        work += len(line)
        label = _label(line, separators)
        if label is None:
            return None, work
        pairs.append(("label", label[0]))
    for block in blocks[1:]:
        work += len(block[0])
        leader = _label(block[0], separators)
        if leader is None:
            return None, work
        if not leader[1].strip(_EDGE):
            if len(block) < 2:
                return None, work
            for body in block[1:]:
                work += len(body)
                if any(separator in body for separator in separators):
                    return None, work
            pairs.append(("section", leader[0]))
            continue
        pairs.append(("label", leader[0]))
        for line in block[1:]:
            work += len(line)
            label = _label(line, separators)
            if label is None:
                return None, work
            pairs.append(("label", label[0]))
    return (title, tuple(pairs)), work


def structure(text: str) -> tuple[str, tuple[tuple[str, str], ...]] | None:
    """Steps 2-4 alone: the title and its structure pairs, or `None` where the grammar refuses."""

    return _structure(text)[0]


def project(program: ProjectionProgram, value: JSONValue) -> Projection:
    """Map one canonical-JSON input to its case key, or name why it has none. Total."""

    if (
        type(value) is not dict
        or set(value) != {program.text, *program.keep}
        or type(value[program.text]) is not str
    ):
        return Projection(matched=False, key=None, reason="input", work=0)
    text = value[program.text]
    assert type(text) is str  # noqa: S101 — narrowing only: checked on the line above
    parsed, work = _structure(text, _SEPARATORS[program_abi(program)])
    if parsed is None:
        return Projection(matched=False, key=None, reason="text", work=work)
    title, pairs = parsed
    matched = False
    for layout in program.layouts:
        if layout.title != title:
            continue
        work += min(len(layout.entries), len(pairs))
        if layout.entries == pairs:
            matched = True
            break
    if not matched:
        return Projection(matched=False, key=None, reason="layout", work=work)
    key_value: dict[str, JSONValue] = {
        "form": {"title": title, "structure": [[kind, key] for kind, key in pairs]},
        "keep": {field: value[field] for field in program.keep},
    }
    try:
        key = canonicalize(key_value)
    except ValidationError:
        return Projection(matched=False, key=None, reason="key", work=work)
    return Projection(matched=True, key=key, reason=None, work=work)


# Outside `__all__` on purpose: the two learning surfaces (CLI `learn cases --projectable`, the Open
# WebUI learning tool) share it, while the projection contract API stays the seven pinned names.
class LayoutDocument(TypedDict):
    name: str
    title: str
    entries: list[dict[str, str]]


class ProgramDocument(TypedDict):
    """The program document `draft_program` derives (p89: typed per field)."""

    abi: str
    text: str
    keep: list[str]
    layouts: list[LayoutDocument]


def draft_program(inputs: list[JSONValue]) -> ProgramDocument:
    """One layout per distinct title + structure of the raw inputs, as a v1 program unless some
    input reads differently under v2's separators (a U+FF1A label): then a v2 program (p97).
    The result always parses: a structure no layout can hold, and layouts past the program's
    count + byte bounds, stay out, so their inputs stay unprojected (the LLM answers them).

    The learning pass decides that an operation is projectable; the program itself is mechanical,
    so it is derived here and nobody copies a label by hand.
    """

    fields = {
        name
        for value in inputs
        if isinstance(value, dict)
        for name, text in value.items()
        if isinstance(text, str)
    }
    if (
        not inputs
        or len(fields) != 1
        or any(
            not isinstance(value, dict)
            or set(value) != fields
            or not all(isinstance(text, str) for text in value.values())
            for value in inputs
        )
    ):
        raise ValidationError("a projection needs inputs that hold exactly one text field")
    (field,) = fields
    _field(field, "projection text")
    texts = [str(cast(dict[str, JSONValue], value)[field]) for value in inputs]
    v2 = _SEPARATORS[PROJECTION_ABI_V2]
    abi = (
        PROJECTION_ABI_V2
        if any(_structure(t, v2)[0] != structure(t) for t in texts)
        else PROJECTION_ABI
    )
    layouts: dict[tuple[str, tuple[tuple[str, str], ...]], LayoutDocument] = {}
    for text in texts:
        parsed = _structure(text, _SEPARATORS[abi])[0]
        if parsed is None or parsed in layouts:
            continue
        title, pairs = parsed
        layout: LayoutDocument = {
            # ASCII-only folding: `str.lower` varies across the supported Unicode databases and
            # can lengthen a valid title past MAX_LITERAL (U+0130 → 2 characters).
            "name": title.translate(_ASCII_LOWER),
            "title": title,
            "entries": [{kind: key} for kind, key in pairs],
        }
        try:
            # A structure the grammar reads but no layout can hold (no entry, an over-long or
            # space-edged title or label) stays out of the program: that input is unprojected.
            parse_program({"abi": abi, "text": field, "keep": [], "layouts": [layout]})
        except ValidationError:
            continue
        layouts[parsed] = layout
    if not layouts:
        raise ValidationError("no input has a form layout that a projection can read")
    program: ProgramDocument = {"abi": abi, "text": field, "keep": [], "layouts": []}
    size = len(canonicalize(program).text.encode())
    for key in sorted(layouts):
        # Layouts past the program bounds stay out, in key order: their inputs are unprojected.
        grown = size + len(canonicalize(layouts[key]).text.encode()) + bool(program["layouts"])
        if len(program["layouts"]) == MAX_LAYOUTS or grown > PROGRAM_MAX_BYTES:
            break
        program["layouts"].append(layouts[key])
        size = grown
    return program
''',
    "shadow": r'''
"""Shadow observations: an LLM's answer to an input a learned function also answered.

Contract: `.agent/decisions/p136-store-contract.md`. Observations live in their own SQLite file
beside the ledger, so an agreement never commits to the ledger and never makes the serving cache
cold. Admission captures what the comparison needs before any model call: the answer of the version
that served the hit and the comparator in force for its revision. A disagreement is first made
durable as `prepared`, then becomes one pending proposal (source id `shadow:<observation id>`); a
retry finds that proposal by its source id instead of writing a second one. Nothing here switches,
promotes, challenges or edits a function.
"""

from __future__ import annotations

import functools
import hashlib
import os
import sqlite3
import time
import unicodedata
from collections.abc import Iterator
from contextlib import contextmanager
from dataclasses import dataclass
from pathlib import Path
from typing import Any, Literal, TypedDict, cast

from .comparator import Comparator, compare, parse_comparator
from .errors import ConflictError, IntegrityError, NotFoundError, StateError, ValidationError
from .json_value import JSONValue, canonicalize, parse_json
from .models import Candidate
from .store import _schema_objects
from .system import (
    _MAX_AGE_SECONDS,
    SOURCE_ID_MAX_BYTES,
    System,
    _digest,
    _entity_id,
    _name,
    _stored_int,
    _text,
)

__all__ = [
    "Admission",
    "DriftGroup",
    "DriftReport",
    "ObservationRecord",
    "ShadowErasure",
    "ShadowStore",
    "admit",
    "cancel",
    "drift",
    "drop",
    "fail",
    "finish_shadow",
    "observations",
    "pending",
    "record_shadow",
    "shadow_path",
]

SHADOW_SCHEMA_VERSION = 1
SOURCE_PREFIX = "shadow:"
# The observation id becomes the ledger source id.
OBSERVATION_ID_MAX_BYTES = SOURCE_ID_MAX_BYTES - len(SOURCE_PREFIX)
TEXT_MAX_BYTES = 256
ANSWER_MAX_BYTES = 1_048_576
PROVENANCE_PATHS = 5
_MAX_INT = 2**63 - 1
State = Literal["admitted", "prepared", "agreed", "disagreed", "failed", "cancelled", "dropped"]
STATES: tuple[State, ...] = (
    "admitted",
    "prepared",
    "agreed",
    "disagreed",
    "failed",
    "cancelled",
    "dropped",
)

SHADOW_SCHEMA = r"""
CREATE TABLE IF NOT EXISTS shadow_metadata (
    key TEXT PRIMARY KEY,
    value TEXT NOT NULL
) STRICT;

CREATE TABLE IF NOT EXISTS observations (
    sequence INTEGER PRIMARY KEY AUTOINCREMENT,
    id TEXT NOT NULL UNIQUE,
    partition TEXT NOT NULL,
    operation TEXT NOT NULL,
    observation_id TEXT NOT NULL,
    function_hash TEXT NOT NULL,
    input_json TEXT NOT NULL,
    input_hash TEXT NOT NULL,
    state TEXT NOT NULL CHECK (
        state IN ('admitted', 'prepared', 'agreed', 'disagreed', 'failed', 'cancelled', 'dropped')
    ),
    receipt_id TEXT,
    operation_revision INTEGER CHECK (operation_revision >= 1),
    function_output_json TEXT,
    artifact_hash TEXT,
    comparator_json TEXT,
    comparator_hash TEXT,
    comparator_sequence INTEGER,
    llm_output_json TEXT,
    differences_json TEXT,
    source_id TEXT,
    proposal_id TEXT,
    model TEXT,
    prompt_revision TEXT,
    note TEXT,
    observed_at_us INTEGER NOT NULL CHECK (observed_at_us >= 0),
    admitted_at_us INTEGER NOT NULL CHECK (admitted_at_us >= 0),
    recorded_at_us INTEGER,
    latency_ms INTEGER CHECK (latency_ms >= 0),
    UNIQUE (partition, operation, observation_id),
    CHECK ((state = 'dropped') = (receipt_id IS NULL)),
    CHECK ((receipt_id IS NULL) = (function_output_json IS NULL)),
    CHECK ((receipt_id IS NULL) = (operation_revision IS NULL)),
    CHECK ((comparator_json IS NULL) = (comparator_hash IS NULL)),
    CHECK ((comparator_json IS NULL) = (comparator_sequence IS NULL)),
    CHECK (state NOT IN ('agreed', 'prepared', 'disagreed') OR (
        llm_output_json IS NOT NULL AND differences_json IS NOT NULL AND model IS NOT NULL
        AND prompt_revision IS NOT NULL AND latency_ms IS NOT NULL AND recorded_at_us IS NOT NULL)),
    CHECK ((state IN ('prepared', 'disagreed')) = (source_id IS NOT NULL)),
    CHECK (state NOT IN ('failed', 'cancelled', 'dropped') OR note IS NOT NULL)
) STRICT;

CREATE TABLE IF NOT EXISTS duplicates (
    partition TEXT NOT NULL,
    operation TEXT NOT NULL,
    count INTEGER NOT NULL CHECK (count >= 1),
    last_at_us INTEGER NOT NULL,
    PRIMARY KEY (partition, operation)
) STRICT;

CREATE INDEX IF NOT EXISTS observations_scope
    ON observations(partition, operation, sequence);
CREATE INDEX IF NOT EXISTS observations_state
    ON observations(state, sequence);

CREATE TRIGGER IF NOT EXISTS observations_state_lifecycle
BEFORE UPDATE OF state ON observations
WHEN NOT (
    NEW.state = OLD.state
    OR (OLD.state = 'admitted' AND NEW.state IN ('agreed', 'prepared', 'failed', 'cancelled'))
    OR (OLD.state = 'prepared' AND NEW.state = 'disagreed')
)
BEGIN
    SELECT RAISE(ABORT, 'invalid observation state transition');
END;
CREATE TRIGGER IF NOT EXISTS observations_capture_immutable
BEFORE UPDATE OF
    sequence, id, partition, operation, observation_id, function_hash, input_json, input_hash,
    receipt_id, operation_revision, function_output_json, artifact_hash, comparator_json,
    comparator_hash, comparator_sequence, observed_at_us, admitted_at_us
ON observations BEGIN
    SELECT RAISE(ABORT, 'an observation keeps its identity and capture');
END;
CREATE TRIGGER IF NOT EXISTS shadow_metadata_no_update
BEFORE UPDATE ON shadow_metadata BEGIN
    SELECT RAISE(ABORT, 'shadow metadata is immutable');
END;
CREATE TRIGGER IF NOT EXISTS shadow_metadata_no_delete
BEFORE DELETE ON shadow_metadata BEGIN
    SELECT RAISE(ABORT, 'shadow metadata is immutable');
END;
"""

SHADOW_FINGERPRINT = hashlib.sha256(SHADOW_SCHEMA.encode("utf-8")).hexdigest()
_METADATA_KEY = f"cement-shadow-v{SHADOW_SCHEMA_VERSION}"


def shadow_path(ledger: str | os.PathLike[str]) -> Path:
    """The shadow store that belongs beside a ledger file."""

    return Path(f"{os.fspath(ledger)}.shadow")


def _statements(script: str) -> Iterator[str]:
    statement = ""
    for line in script.splitlines(keepends=True):
        statement += line
        if sqlite3.complete_statement(statement):
            yield statement
            statement = ""


@functools.cache
def _expected_objects() -> dict[tuple[str, str], str]:
    # Built once: the filter opens the store once per sampled hit.
    connection = sqlite3.connect(":memory:")
    try:
        for statement in _statements(SHADOW_SCHEMA):
            connection.execute(statement)
        return _schema_objects(connection)
    finally:
        connection.close()


def _bounded_text(value: object, label: str, maximum: int) -> str:
    if type(value) is not str or not value:
        raise ValidationError(f"{label} must be non-empty text")
    try:
        size = len(value.encode("utf-8"))
    except UnicodeEncodeError:
        raise ValidationError(f"{label} must contain valid Unicode scalar values") from None
    if size > maximum:
        raise ValidationError(f"{label} exceeds {maximum} UTF-8 bytes")
    if any(unicodedata.category(character) == "Cc" for character in value):
        raise ValidationError(f"{label} must not contain control characters")
    return value


def _bounded_int(value: object, label: str) -> int:
    if type(value) is not int or not 0 <= value <= _MAX_INT:
        raise ValidationError(f"{label} must be an integer from 0 to {_MAX_INT}")
    return value


def _now_us() -> int:
    return time.time_ns() // 1_000


class ShadowStore:
    """The shadow observation file. Connections are short-lived, as in the ledger's store."""

    def __init__(self, path: str | os.PathLike[str], *, create: bool = True) -> None:
        if type(create) is not bool:
            raise ValidationError("create must be a boolean")
        try:
            self.path = Path(path)
        except (TypeError, ValueError) as exc:
            raise ValidationError("shadow store path must be text or a path-like value") from exc
        text = str(self.path)
        if "\0" in text or text == ":memory:":
            raise ValidationError("shadow store path must name a file")
        try:
            self.path = self.path.absolute()  # as `Store`: a later `chdir` keeps this file
        except OSError as exc:
            raise ValidationError("shadow store path is relative to a missing directory") from exc
        if self.path.is_symlink():
            raise ValidationError("shadow store path must not be a symbolic link")
        if self.path.exists() and not self.path.is_file():
            raise ValidationError("shadow store path must identify a regular file")
        if not self.path.exists():
            if not create:
                raise NotFoundError("shadow store file is missing")
            try:
                descriptor = os.open(self.path, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
            except FileExistsError:
                pass
            except OSError as exc:
                raise ValidationError("shadow store path could not be created safely") from exc
            else:
                try:
                    os.fchmod(descriptor, 0o600)  # as `Store`: the umask masks `os.open`'s mode
                finally:
                    os.close(descriptor)
        self._open(initialize=create)

    def _connect(self) -> sqlite3.Connection:
        connection = sqlite3.connect(self.path, timeout=10.0, isolation_level=None)
        try:
            connection.row_factory = sqlite3.Row
            connection.execute("PRAGMA foreign_keys = ON")
            connection.execute("PRAGMA synchronous = EXTRA")
            connection.execute("PRAGMA temp_store = MEMORY")
            connection.execute("PRAGMA trusted_schema = OFF")
            # A pruned or erased observation leaves no copy in the file (as in the ledger).
            connection.execute("PRAGMA secure_delete = ON")
            connection.setconfig(sqlite3.SQLITE_DBCONFIG_DEFENSIVE, True)
        except Exception:
            connection.close()
            raise
        return connection

    def _open(self, *, initialize: bool) -> None:
        try:
            with self.transaction() as connection:
                version = int(connection.execute("PRAGMA user_version").fetchone()[0])
                if version == 0:
                    # As the ledger: only a creating open initializes, and only a pristine file.
                    if (
                        not initialize
                        or connection.execute("SELECT 1 FROM sqlite_master LIMIT 1").fetchone()
                        or int(connection.execute("PRAGMA application_id").fetchone()[0]) != 0
                    ):
                        raise IntegrityError("the file is not a Cement shadow store")
                    for statement in _statements(SHADOW_SCHEMA):
                        connection.execute(statement)
                    connection.execute(
                        "INSERT INTO shadow_metadata(key, value) VALUES (?, ?)",
                        (_METADATA_KEY, SHADOW_FINGERPRINT),
                    )
                    connection.execute(f"PRAGMA user_version = {SHADOW_SCHEMA_VERSION}")
                elif (
                    connection.execute(
                        "SELECT 1 FROM sqlite_master WHERE type = 'table'"
                        " AND name = 'shadow_metadata'"
                    ).fetchone()
                    is None
                ):
                    raise IntegrityError("the file is not a Cement shadow store")
                elif version != SHADOW_SCHEMA_VERSION:
                    raise IntegrityError(f"shadow store schema {version} is unsupported")
                try:
                    stored = connection.execute(
                        "SELECT value FROM shadow_metadata WHERE key = ?", (_METADATA_KEY,)
                    ).fetchone()
                except sqlite3.DatabaseError:
                    raise IntegrityError("the file is not a Cement shadow store") from None
                if stored is None or stored[0] != SHADOW_FINGERPRINT:
                    raise IntegrityError("shadow store schema fingerprint mismatch")
                if _schema_objects(connection) != _expected_objects():
                    raise IntegrityError("shadow store schema does not match the runtime schema")
            # Journal policy changes only after identity is established (as the ledger): a file an
            # operator switched to WAL returns to a rollback journal.
            connection = self._connect()
            try:
                connection.execute("PRAGMA journal_mode = DELETE")
            finally:
                connection.close()
        except StateError:
            raise
        except sqlite3.OperationalError as exc:
            raise StateError("shadow store is busy or unavailable") from exc
        except sqlite3.DatabaseError as exc:
            raise IntegrityError("the file is not a Cement shadow store") from exc

    @contextmanager
    def transaction(self) -> Iterator[sqlite3.Connection]:
        """One write-locked transaction; a raised exception rolls it back."""

        connection = self._connect()
        try:
            connection.execute("BEGIN IMMEDIATE")
            try:
                yield connection
            except BaseException:
                connection.rollback()
                raise
            connection.commit()
        except sqlite3.OperationalError as exc:
            raise StateError("shadow store is busy or unavailable") from exc
        finally:
            connection.close()

    def prune(self, partition: str, *, older_than_seconds: int) -> int:
        """Delete the partition's observations observed before now minus the age, every state;
        returns the count. A pruned identity can be admitted again."""

        partition = _name(partition, "partition")
        if type(older_than_seconds) is not int or not 0 <= older_than_seconds <= _MAX_AGE_SECONDS:
            raise ValidationError(
                f"older_than_seconds must be an integer from 0 to {_MAX_AGE_SECONDS}"
            )
        with self.transaction() as connection:
            cutoff = _now_us() - older_than_seconds * 1_000_000
            return int(
                connection.execute(
                    "DELETE FROM observations WHERE partition = ? AND observed_at_us < ?",
                    (partition, cutoff),
                ).rowcount
            )

    def erase(self, partition: str) -> ShadowErasure:
        """Delete every observation and the duplicate counters of the partition."""

        partition = _name(partition, "partition")
        with self.transaction() as connection:
            return {
                "observations": int(
                    connection.execute(
                        "DELETE FROM observations WHERE partition = ?", (partition,)
                    ).rowcount
                ),
                "duplicates": int(
                    connection.execute(
                        "DELETE FROM duplicates WHERE partition = ?", (partition,)
                    ).rowcount
                ),
            }


class ShadowErasure(TypedDict):
    observations: int
    duplicates: int


