_INSERT_COLUMNS = (
    "id",
    "partition",
    "operation",
    "observation_id",
    "function_hash",
    "input_json",
    "input_hash",
    "state",
    "receipt_id",
    "operation_revision",
    "function_output_json",
    "artifact_hash",
    "comparator_json",
    "comparator_hash",
    "comparator_sequence",
    "note",
    "observed_at_us",
    "admitted_at_us",
)
_INSERT = (
    f"INSERT INTO observations({', '.join(_INSERT_COLUMNS)})"  # noqa: S608 — a fixed column list
    f" VALUES ({', '.join('?' for _ in _INSERT_COLUMNS)})"
)


def _insert(store: ShadowStore, values: dict[str, object]) -> Admission:
    """One new row, or — for a repeated identity — the duplicate counter + 1 and the original id."""

    now = cast(int, values["admitted_at_us"])
    with store.transaction() as connection:
        existing = connection.execute(
            "SELECT id FROM observations"
            " WHERE partition = ? AND operation = ? AND observation_id = ?",
            (values["partition"], values["operation"], values["observation_id"]),
        ).fetchone()
        if existing is not None:
            connection.execute(
                """
                INSERT INTO duplicates(partition, operation, count, last_at_us)
                VALUES (?, ?, 1, ?)
                ON CONFLICT(partition, operation)
                DO UPDATE SET count = count + 1, last_at_us = excluded.last_at_us
                """,
                (values["partition"], values["operation"], now),
            )
            return Admission(admitted=False, id=str(existing["id"]))
        connection.execute(_INSERT, tuple(values.get(column) for column in _INSERT_COLUMNS))
    return Admission(admitted=True, id=cast(str, values["id"]))


def admit(
    system: System,
    store: ShadowStore,
    partition: str,
    operation: str,
    *,
    observation_id: str,
    function_hash: str,
    input_value: object,
    observed_at_us: int,
) -> Admission:
    """Admit one hit before any model work, capturing the answer of the version that served it
    and the comparator in force for its revision. A repeated observation id writes no row, counts
    one duplicate and returns the original row's id."""

    partition, operation = _scope(partition, operation)
    observation_id = _observation_id(observation_id)
    observed_at_us = _bounded_int(observed_at_us, "observed_at_us")
    canonical = canonicalize(input_value)
    capture = system.shadow_capture(
        partition, operation, function_hash=function_hash, input_value=input_value
    )
    comparator = capture.comparator
    return _insert(
        store,
        {
            "id": "ob_" + os.urandom(16).hex(),
            "partition": partition,
            "operation": operation,
            "observation_id": observation_id,
            "function_hash": capture.function_hash,
            "input_json": canonical.text,
            "input_hash": canonical.digest,
            "state": "admitted",
            "receipt_id": capture.receipt_id,
            "operation_revision": capture.operation_revision,
            "function_output_json": canonicalize(capture.output).text,
            "artifact_hash": capture.artifact_hash,
            "comparator_json": None
            if comparator is None
            else canonicalize(comparator["comparator"]).text,
            "comparator_hash": None if comparator is None else comparator["comparator_hash"],
            "comparator_sequence": None if comparator is None else comparator["sequence"],
            "observed_at_us": observed_at_us,
            "admitted_at_us": _now_us(),
        },
    )


def drop(
    store: ShadowStore,
    partition: str,
    operation: str,
    *,
    observation_id: str,
    function_hash: str,
    input_value: object,
    observed_at_us: int,
    reason: str,
) -> Admission:
    """Record a hit that never reached the model (a full queue) as ``dropped``, without capture."""

    partition, operation = _scope(partition, operation)
    observation_id = _observation_id(observation_id)
    canonical = canonicalize(input_value)
    return _insert(
        store,
        {
            "id": "ob_" + os.urandom(16).hex(),
            "partition": partition,
            "operation": operation,
            "observation_id": observation_id,
            "function_hash": _digest(function_hash, "function_hash"),
            "input_json": canonical.text,
            "input_hash": canonical.digest,
            "state": "dropped",
            "note": _bounded_text(reason, "reason", TEXT_MAX_BYTES),
            "observed_at_us": _bounded_int(observed_at_us, "observed_at_us"),
            "admitted_at_us": _now_us(),
        },
    )


def _leave_admitted(
    store: ShadowStore, ident: str, state: State, fields: dict[str, object]
) -> None:
    assignments = ", ".join(f"{column} = ?" for column in fields)
    statement = (
        f"UPDATE observations SET state = ?, {assignments} WHERE id = ? AND state = 'admitted'"  # noqa: S608 — fixed column names
    )
    with store.transaction() as connection:
        if connection.execute(statement, (state, *fields.values(), ident)).rowcount != 1:
            raise ConflictError("the observation is not admitted")


def cancel(store: ShadowStore, ident: str, *, reason: str) -> None:
    """``admitted`` → ``cancelled``: admitted work that will not reach the model (a shutdown)."""

    ident = _row_id(ident)
    note = _bounded_text(reason, "reason", TEXT_MAX_BYTES)
    _leave_admitted(store, ident, "cancelled", {"note": note, "recorded_at_us": _now_us()})


def fail(
    store: ShadowStore,
    ident: str,
    *,
    reason: str,
    model: str,
    prompt_revision: str,
    latency_ms: int,
) -> None:
    """``admitted`` → ``failed``: the model call failed, timed out or gave no usable answer."""

    ident = _row_id(ident)
    fields: dict[str, object] = {
        "note": _bounded_text(reason, "reason", TEXT_MAX_BYTES),
        "model": _bounded_text(model, "model", TEXT_MAX_BYTES),
        "prompt_revision": _bounded_text(prompt_revision, "prompt_revision", TEXT_MAX_BYTES),
        "latency_ms": _bounded_int(latency_ms, "latency_ms"),
        "recorded_at_us": _now_us(),
    }
    _leave_admitted(store, ident, "failed", fields)


def _json(text: object, label: str) -> JSONValue:
    if text is None:
        return None
    try:
        return parse_json(str(text), max_bytes=ANSWER_MAX_BYTES).value
    except ValidationError as exc:
        raise IntegrityError(f"stored {label} is invalid") from exc


def _captured_comparator(row: sqlite3.Row) -> Comparator | None:
    """The comparator an observation captured, re-checked against its stored hash."""

    if row["comparator_json"] is None:
        return None
    try:
        comparator = parse_comparator(_json(row["comparator_json"], "comparator"))
    except ValidationError:
        raise IntegrityError("stored comparator is invalid") from None
    if comparator.comparator_hash != row["comparator_hash"]:
        raise IntegrityError("stored comparator does not match its hash")
    return comparator


def _record(row: sqlite3.Row) -> ObservationRecord:
    input_value = _json(row["input_json"], "input")
    if canonicalize(input_value).digest != row["input_hash"]:
        raise IntegrityError("stored observation input does not match its hash")
    _captured_comparator(row)
    state = str(row["state"])
    if state not in STATES:
        raise IntegrityError("stored observation state is invalid")
    differences = _json(row["differences_json"], "differences")
    if differences is not None and not (
        isinstance(differences, list) and all(isinstance(path, str) for path in differences)
    ):
        raise IntegrityError("stored observation differences are invalid")

    def number(name: str, minimum: int = 0) -> int | None:
        value = row[name]
        return None if value is None else _stored_int(value, f"observation {name}", minimum=minimum)

    def text(name: str) -> str | None:
        value = row[name]
        return None if value is None else str(value)

    return {
        "sequence": _stored_int(row["sequence"], "observation sequence", minimum=1),
        "id": str(row["id"]),
        "partition": str(row["partition"]),
        "operation": str(row["operation"]),
        "observation_id": str(row["observation_id"]),
        "function_hash": str(row["function_hash"]),
        "input": input_value,
        "state": state,
        "receipt_id": text("receipt_id"),
        "operation_revision": number("operation_revision", 1),
        "function_output": _json(row["function_output_json"], "function output"),
        "comparator_hash": text("comparator_hash"),
        "comparator_sequence": number("comparator_sequence", 1),
        "llm_output": _json(row["llm_output_json"], "LLM output"),
        "differences": [] if differences is None else cast(list[str], differences),
        "source_id": text("source_id"),
        "proposal_id": text("proposal_id"),
        "model": text("model"),
        "prompt_revision": text("prompt_revision"),
        "note": text("note"),
        "observed_at_us": _stored_int(row["observed_at_us"], "observation observed_at_us"),
        "admitted_at_us": _stored_int(row["admitted_at_us"], "observation admitted_at_us"),
        "recorded_at_us": number("recorded_at_us"),
        "latency_ms": number("latency_ms"),
    }


def _row(connection: sqlite3.Connection, ident: str) -> sqlite3.Row:
    row = connection.execute("SELECT * FROM observations WHERE id = ?", (ident,)).fetchone()
    if row is None:
        raise NotFoundError("the observation does not exist")
    return cast(sqlite3.Row, row)


def record_shadow(
    system: System,
    store: ShadowStore,
    ident: str,
    *,
    llm_output: object,
    model: str,
    prompt_revision: str,
    latency_ms: int,
) -> ObservationRecord:
    """Record the LLM's answer for an admitted observation and decide agreement against the
    CAPTURED answer + comparator. An agreement writes the shadow store alone; a disagreement is
    made durable as ``prepared`` and then finished into one pending proposal (``finish_shadow``)."""

    ident = _row_id(ident)
    answer = canonicalize(llm_output, max_bytes=ANSWER_MAX_BYTES)
    model = _bounded_text(model, "model", TEXT_MAX_BYTES)
    prompt_revision = _bounded_text(prompt_revision, "prompt_revision", TEXT_MAX_BYTES)
    latency_ms = _bounded_int(latency_ms, "latency_ms")
    with store.transaction() as connection:
        row = _row(connection, ident)
        if row["state"] != "admitted":
            raise ConflictError(f"the observation is {row['state']}, not admitted")
        verdict = compare(
            _captured_comparator(row),
            _json(row["function_output_json"], "function output"),
            answer.value,
        )
        connection.execute(
            """
            UPDATE observations SET state = ?, llm_output_json = ?, differences_json = ?,
                source_id = ?, model = ?, prompt_revision = ?, latency_ms = ?, recorded_at_us = ?
            WHERE id = ? AND state = 'admitted'
            """,
            (
                "agreed" if verdict.agreed else "prepared",
                answer.text,
                canonicalize(list[JSONValue](verdict.paths)).text,
                None if verdict.agreed else SOURCE_PREFIX + str(row["observation_id"]),
                model,
                prompt_revision,
                latency_ms,
                _now_us(),
                ident,
            ),
        )
        if verdict.agreed:
            return _record(_row(connection, ident))
    return finish_shadow(system, store, ident)


def _provenance(row: sqlite3.Row, differences: list[str]) -> dict[str, JSONValue]:
    shadow: dict[str, JSONValue] = {
        "observation_id": str(row["observation_id"]),
        "function_hash": str(row["function_hash"]),
        "receipt_id": str(row["receipt_id"]),
        "comparator_hash": None if row["comparator_hash"] is None else str(row["comparator_hash"]),
        "model": str(row["model"]),
        "prompt_revision": str(row["prompt_revision"]),
        "difference_count": len(differences),
        "differences": list[JSONValue](differences[:PROVENANCE_PATHS]),
    }
    return {"shadow": shadow}


def _matches(
    existing: Any,
    row: sqlite3.Row,
    answer_digest: str,
    revision: int,
    provenance: dict[str, JSONValue],
) -> bool:
    # An earlier attempt wrote exactly this provenance from the same prepared row.
    return bool(
        canonicalize(existing["input"]).digest == row["input_hash"]
        and canonicalize(existing["proposed_output"]).digest == answer_digest
        and existing["operation_revision"] == revision
        and canonicalize(existing["provenance"]).digest == canonicalize(provenance).digest
    )


def finish_shadow(system: System, store: ShadowStore, ident: str) -> ObservationRecord:
    """Turn a ``prepared`` disagreement into one pending proposal and mark it ``disagreed``.

    Lock order: the shadow store, then the ledger. An earlier attempt's proposal is found by its
    source id in any status and must match the prepared payload (``ConflictError`` otherwise; the
    row stays ``prepared``). A captured revision that is no longer current writes no proposal.
    """

    ident = _row_id(ident)
    with store.transaction() as connection:
        row = _row(connection, ident)
        if row["state"] != "prepared":
            raise ConflictError(f"the observation is {row['state']}, not prepared")
        partition, operation = str(row["partition"]), str(row["operation"])
        source_id = str(row["source_id"])
        answer = canonicalize(_json(row["llm_output_json"], "LLM output"))
        revision = int(row["operation_revision"])
        paths = _json(row["differences_json"], "differences")
        differences = [str(path) for path in paths] if isinstance(paths, list) else []
        proposal_id: str | None = None
        note: str | None = None
        existing = system.proposal_by_source(partition, operation, source_id)
        if existing is not None:
            if not _matches(existing, row, answer.digest, revision, _provenance(row, differences)):
                raise ConflictError(
                    f"source id {source_id} names a proposal that does not match this observation"
                )
            proposal_id = existing["id"]
        else:
            current = next(
                (
                    record["revision"]
                    for record in system.operations(partition)
                    if record["name"] == operation
                ),
                None,
            )
            if current != revision:
                note = f"no proposal: the operation moved from revision {revision} to {current}"
            else:
                try:
                    proposal_id = system.submit_proposal(
                        partition,
                        operation,
                        _json(row["input_json"], "input"),
                        candidate=Candidate(
                            output=answer.value, provenance=_provenance(row, differences)
                        ),
                        source_id=source_id,
                        expected_revision=revision,
                    )
                except StateError as exc:
                    if "revision" not in str(exc):
                        raise
                    note = f"no proposal: {exc}"
        connection.execute(
            """
            UPDATE observations SET state = 'disagreed', proposal_id = ?, note = ?
            WHERE id = ? AND state = 'prepared'
            """,
            (proposal_id, note, ident),
        )
        return _record(_row(connection, ident))


def _limit(value: object) -> int:
    if type(value) is not int or not 1 <= value <= 1_000:
        raise ValidationError("limit must be an integer from 1 to 1000")
    return value


def drift(
    store: ShadowStore, partition: str, operation: str, *, since_us: int | None = None
) -> DriftReport:
    """Per-version counts of the observations at or after ``since_us`` (all when ``None``);
    ``disagreements`` = prepared + disagreed; ``duplicates`` = the lifetime repeat counter."""

    partition, operation = _scope(partition, operation)
    floor = 0 if since_us is None else _bounded_int(since_us, "since_us")
    groups: dict[str, DriftGroup] = {}
    totals: dict[str, int] = dict.fromkeys(STATES, 0)
    with store.transaction() as connection:
        for row in connection.execute(
            """
            SELECT function_hash, state, MIN(sequence) AS first, COUNT(*) AS n
            FROM observations
            WHERE partition = ? AND operation = ? AND observed_at_us >= ?
            GROUP BY function_hash, state
            """,
            (partition, operation, floor),
        ):
            state = str(row["state"])
            if state not in STATES:
                raise IntegrityError("stored observation state is invalid")
            digest, first, count = str(row["function_hash"]), int(row["first"]), int(row["n"])
            group = groups.setdefault(
                digest,
                {
                    "function_hash": digest,
                    "first_sequence": first,
                    "counts": dict.fromkeys(STATES, 0),
                },
            )
            group["first_sequence"] = min(group["first_sequence"], first)
            group["counts"][state] = count
            totals[state] += count
        repeated = connection.execute(
            "SELECT count FROM duplicates WHERE partition = ? AND operation = ?",
            (partition, operation),
        ).fetchone()
    return {
        "partition": partition,
        "operation": operation,
        "since_us": since_us,
        "groups": sorted(groups.values(), key=lambda group: group["first_sequence"]),
        "totals": totals,
        "disagreements": totals["prepared"] + totals["disagreed"],
        "duplicates": 0 if repeated is None else int(repeated["count"]),
    }


def observations(
    store: ShadowStore,
    partition: str,
    operation: str,
    *,
    state: str | None = None,
    function_hash: str | None = None,
    after_sequence: int = 0,
    limit: int = 100,
) -> list[ObservationRecord]:
    """One page of observations in sequence order, every stored field included."""

    partition, operation = _scope(partition, operation)
    if state is not None and state not in STATES:
        raise ValidationError(f"state must be one of {', '.join(STATES)}")
    if function_hash is not None:
        function_hash = _digest(function_hash, "function_hash")
    after_sequence = _bounded_int(after_sequence, "after_sequence")
    limit = _limit(limit)
    with store.transaction() as connection:
        rows = connection.execute(
            """
            SELECT * FROM observations
            WHERE partition = ? AND operation = ? AND sequence > ?
              AND (? IS NULL OR state = ?) AND (? IS NULL OR function_hash = ?)
            ORDER BY sequence LIMIT ?
            """,
            (
                partition,
                operation,
                after_sequence,
                state,
                state,
                function_hash,
                function_hash,
                limit,
            ),
        ).fetchall()
        return [_record(row) for row in rows]


def pending(
    store: ShadowStore,
    *,
    state: Literal["admitted", "prepared"] = "admitted",
    after_sequence: int = 0,
    limit: int = 100,
) -> list[ObservationRecord]:
    """Observations awaiting a model answer (``admitted``) or a finish (``prepared``), oldest
    first, across every scope: a cursor for ONE batch consumer, never a lease."""

    if state not in ("admitted", "prepared"):
        raise ValidationError("state must be admitted or prepared")
    after_sequence = _bounded_int(after_sequence, "after_sequence")
    limit = _limit(limit)
    with store.transaction() as connection:
        rows = connection.execute(
            "SELECT * FROM observations WHERE state = ? AND sequence > ? ORDER BY sequence LIMIT ?",
            (state, after_sequence, limit),
        ).fetchall()
        return [_record(row) for row in rows]
''',
    "signature": r'''
"""Bundle signatures: OpenSSH SSHSIG envelopes over Ed25519, verified in pure Python.

Cement never signs: a person signs an exported bundle with ``ssh-keygen -Y sign -n
cement-function-v3``, and a consumer checks it against an allowed-signers file before the bundle
parses. Verification reads only public data (the key, the signature, the signed bytes), so no branch
depends on a secret and constant-time arithmetic buys nothing; that is why stdlib big integers
suffice. The Ed25519 check is RFC 8032 section 5.1.7 under a strict policy: canonical encodings,
``S < L``, a prime-order key, and the cofactorless equation.
"""

from __future__ import annotations

import base64
import binascii
import hashlib
from dataclasses import dataclass

from .errors import IntegrityError, ValidationError

FUNCTION_NAMESPACE = "cement-function-v3"
SIGNATURE_MAX_BYTES = 65_536
ALLOWED_SIGNERS_MAX_BYTES = 1_048_576

# edwards25519 (RFC 8032 section 5.1); points in extended coordinates (X, Y, Z, T).
_P = 2**255 - 19
_D = -121665 * pow(121666, -1, _P) % _P
_L = 2**252 + 27742317777372353535851937790883648493
_SQRT_M1 = pow(2, (_P - 1) // 4, _P)

type _Point = tuple[int, int, int, int]

_IDENTITY: _Point = (0, 1, 1, 0)

_ED25519 = b"ssh-ed25519"
_FIDO = frozenset({b"sk-ssh-ed25519@openssh.com", b"sk-ecdsa-sha2-nistp256@openssh.com"})
_HASHES = frozenset({b"sha256", b"sha512"})
_BEGIN = "-----BEGIN SSH SIGNATURE-----"
_END = "-----END SSH SIGNATURE-----"
_PATTERN = frozenset("*?!")


def _add(left: _Point, right: _Point) -> _Point:
    x1, y1, z1, t1 = left
    x2, y2, z2, t2 = right
    a = (y1 - x1) * (y2 - x2) % _P
    b = (y1 + x1) * (y2 + x2) % _P
    c = 2 * t1 * t2 * _D % _P
    d = 2 * z1 * z2 % _P
    e, f, g, h = b - a, d - c, d + c, b + a
    return (e * f % _P, g * h % _P, f * g % _P, e * h % _P)


def _multiply(scalar: int, point: _Point) -> _Point:
    result = _IDENTITY
    while scalar:
        if scalar & 1:
            result = _add(result, point)
        point = _add(point, point)
        scalar >>= 1
    return result


def _equal(left: _Point, right: _Point) -> bool:
    return (left[0] * right[2] - right[0] * left[2]) % _P == 0 and (
        left[1] * right[2] - right[1] * left[2]
    ) % _P == 0


def _decode_point(raw: bytes) -> _Point | None:
    """A canonical 32-byte encoding, or ``None`` (RFC 8032 section 5.1.3)."""

    if len(raw) != 32:
        return None
    y = int.from_bytes(raw, "little")
    sign = y >> 255
    y &= (1 << 255) - 1
    if y >= _P:
        return None
    square = (y * y - 1) * pow(_D * y * y + 1, -1, _P) % _P
    if square == 0:
        return None if sign else (0, y, 1, 0)
    x = pow(square, (_P + 3) // 8, _P)
    if (x * x - square) % _P:
        x = x * _SQRT_M1 % _P
    if (x * x - square) % _P:
        return None
    if x & 1 != sign:
        x = _P - x
    return (x, y, 1, x * y % _P)


_BX = 15112221349535400772501151409588531511454012693041857206046113283949847762202
_BY = 46316835694926478169428394003475163141307993866256225615783033603165251855960
_BASE: _Point = (_BX, _BY, 1, _BX * _BY % _P)


def _ed25519_verify(public: bytes, message: bytes, signature: bytes) -> bool:
    """RFC 8032 Ed25519 verification under the strict policy; never raises on bytes input."""

    if len(public) != 32 or len(signature) != 64:
        return False
    key = _decode_point(public)
    r = _decode_point(signature[:32])
    if key is None or r is None:
        return False
    s = int.from_bytes(signature[32:], "little")
    if s >= _L:
        return False
    # Small-order and mixed-order keys satisfy only the cofactored equation; an honest key [a]B
    # has prime order, so refusing them never refuses an ssh-keygen signature.
    if _equal(_multiply(8, key), _IDENTITY) or not _equal(_multiply(_L, key), _IDENTITY):
        return False
    k = int.from_bytes(hashlib.sha512(signature[:32] + public + message).digest(), "little") % _L
    return _equal(_multiply(s, _BASE), _add(r, _multiply(k, key)))


class _Wire:
    """RFC 4251 ``uint32`` + ``string`` reader over one buffer."""

    def __init__(self, data: bytes, label: str) -> None:
        self.data = data
        self.at = 0
        self.label = label

    def _take(self, size: int) -> bytes:
        if self.at + size > len(self.data):
            raise ValidationError(f"{self.label} is truncated")
        chunk = self.data[self.at : self.at + size]
        self.at += size
        return chunk

    def uint32(self) -> int:
        return int.from_bytes(self._take(4), "big")

    def string(self) -> bytes:
        return self._take(self.uint32())

    def end(self) -> None:
        if self.at != len(self.data):
            raise ValidationError(f"{self.label} has trailing bytes")


def _string(value: bytes) -> bytes:
    return len(value).to_bytes(4, "big") + value


def _shown(value: bytes) -> str:
    return value[:64].decode("ascii", "replace")


def _ed25519_key(blob: bytes, label: str, prefix: str = "") -> bytes:
    """The 32-byte key of an ``ssh-ed25519`` key blob; ``prefix`` locates a refusal."""

    wire = _Wire(blob, prefix + label)
    name = wire.string()
    if name in _FIDO:
        raise ValidationError(
            f"{prefix}{_shown(name)} is a FIDO security key type; Cement verifies ssh-ed25519"
            " keys only"
        )
    if name != _ED25519:
        raise ValidationError(f"{prefix}key type {_shown(name)} is unsupported; use ssh-ed25519")
    key = wire.string()
    wire.end()
    if len(key) != 32:
        raise ValidationError(f"{prefix}{label} is not a 32-byte Ed25519 key")
    return key


@dataclass(frozen=True, slots=True)
class _Envelope:
    key_blob: bytes
    key: bytes
    namespace: bytes
    reserved: bytes
    hash_algorithm: bytes
    signature: bytes


def _read_sshsig(text: str) -> _Envelope:
    """One armored SSHSIG envelope (PROTOCOL.sshsig), read strictly."""

    lines = [line.removesuffix("\r") for line in text.split("\n")]
    while lines and lines[-1] == "":
        lines.pop()
    if len(lines) < 3 or lines[0] != _BEGIN or lines[-1] != _END:
        raise ValidationError("signature is not an armored SSH signature")
    try:
        blob = binascii.a2b_base64("".join(lines[1:-1]).encode("ascii"), strict_mode=True)
    except (binascii.Error, UnicodeEncodeError):
        raise ValidationError("signature armor is not valid base64") from None
    if blob[:6] != b"SSHSIG":
        raise ValidationError("signature is not an SSHSIG envelope")
    wire = _Wire(blob[6:], "signature")
    version = wire.uint32()
    if version != 1:
        raise ValidationError(f"SSH signature version {version} is unsupported")
    key_blob = wire.string()
    key = _ed25519_key(key_blob, "signature public key")
    namespace = wire.string()
    if not namespace:
        raise ValidationError("signature namespace is empty")
    reserved = wire.string()
    hash_algorithm = wire.string()
    if hash_algorithm not in _HASHES:
        raise ValidationError(f"signature hash algorithm {_shown(hash_algorithm)} is unsupported")
    signature = _Wire(wire.string(), "signature value")
    wire.end()
    if signature.string() != _ED25519:
        raise ValidationError("signature key type differs from its public key")
    value = signature.string()
    signature.end()
    if len(value) != 64:
        raise ValidationError("signature value is not 64 bytes")
    return _Envelope(key_blob, key, namespace, reserved, hash_algorithm, value)


@dataclass(frozen=True, slots=True)
class _Signer:
    principals: tuple[str, ...]
    namespaces: tuple[str, ...] | None
    key: bytes


def _token(line: str, at: int, number: int) -> tuple[str, int]:
    """The next whitespace-delimited token; double quotes protect spaces (no escapes)."""

    while at < len(line) and line[at] in " \t":
        at += 1
    start, quoted = at, False
    while at < len(line) and (quoted or line[at] not in " \t"):
        quoted ^= line[at] == '"'
        at += 1
    if quoted:
        raise ValidationError(f"allowed signers line {number}: a quote is not closed")
    return line[start:at], at


def _split(text: str) -> list[str]:
    """Comma-separated parts; commas inside double quotes stay in their part."""

    parts: list[str] = []
    start, quoted = 0, False
    for at, character in enumerate(text):
        if character == '"':
            quoted = not quoted
        elif character == "," and not quoted:
            parts.append(text[start:at])
            start = at + 1
    parts.append(text[start:])
    return parts


def _names(text: str, what: str, number: int) -> tuple[str, ...]:
    names = tuple(text.split(","))
    if any(not name for name in names):
        raise ValidationError(f"allowed signers line {number}: an empty {what}")
    if any(_PATTERN & set(name) for name in names):
        raise ValidationError(
            f"allowed signers line {number}: {what} patterns are unsupported; list exact names"
        )
    return names


def _is_key_type(token: str) -> bool:
    return token.startswith(("ssh-", "ecdsa-sha2-", "sk-")) or token.endswith(
        "-cert-v01@openssh.com"
    )


def _options(text: str, number: int) -> tuple[str, ...] | None:
    namespaces: tuple[str, ...] | None = None
    for option in _split(text):
        keyword, _, value = option.partition("=")
        if keyword.lower() != "namespaces":
            raise ValidationError(
                f"allowed signers line {number}: option {keyword[:64]} is unsupported"
            )
        if namespaces is not None:
            raise ValidationError(f"allowed signers line {number}: namespaces is repeated")
        if len(value) < 2 or value[0] != '"' or value[-1] != '"':
            raise ValidationError(f"allowed signers line {number}: namespaces must be quoted")
        namespaces = _names(value[1:-1], "namespace", number)
    return namespaces


def _read_allowed_signers(text: str) -> tuple[_Signer, ...]:
    """The ``ssh-ed25519`` lines of an allowed-signers file (``ssh-keygen(1)``, a strict subset)."""

    signers: list[_Signer] = []
    for number, raw in enumerate(text.split("\n"), start=1):
        line = raw.removesuffix("\r")
        stripped = line.lstrip(" \t")
        if not stripped or stripped.startswith("#"):
            continue
        principals, at = _token(line, 0, number)
        if len(principals) >= 2 and principals[0] == principals[-1] == '"':
            principals = principals[1:-1]
        names = _names(principals, "principal", number)
        token, at = _token(line, at, number)
        namespaces = None
        if token and not _is_key_type(token):
            namespaces = _options(token, number)
            token, at = _token(line, at, number)
        if not _is_key_type(token):
            raise ValidationError(f"allowed signers line {number}: no key type")
        encoded, at = _token(line, at, number)
        if not encoded:
            raise ValidationError(f"allowed signers line {number}: no key")
        if token != _ED25519.decode():
            continue  # never trusted, so skipping it cannot accept anything
        try:
            blob = binascii.a2b_base64(encoded.encode("ascii"), strict_mode=True)
        except (binascii.Error, UnicodeEncodeError):
            raise ValidationError(f"allowed signers line {number}: the key is not base64") from None
        key = _ed25519_key(blob, "the key", f"allowed signers line {number}: ")
        signers.append(_Signer(names, namespaces, key))
    return tuple(signers)


@dataclass(frozen=True, slots=True)
class SignatureVerification:
    """A verified signature: the allowed principals of its key, the key's fingerprint as
    ``ssh-keygen`` prints it, and the hash algorithm the signer chose."""

    principals: tuple[str, ...]
    fingerprint: str
    hash_algorithm: str


def verify_signature(
    data: bytes,
    signature: str,
    allowed_signers: str,
    *,
    namespace: str,
    signer: str | None = None,
) -> SignatureVerification:
    """Verify an armored SSHSIG ``signature`` over ``data`` against ``allowed_signers``.

    Refusals: malformed or unsupported input → ``ValidationError``; a namespace, signer or
    signature that does not match → ``IntegrityError``. A key that ``allowed_signers`` lists without
    a ``namespaces`` option is allowed for every namespace. ``data`` is hashed whole, so the caller
    bounds it.
    """

    if type(data) is not bytes:
        raise ValidationError("signed data must be bytes")
    if type(signature) is not str or type(allowed_signers) is not str:
        raise ValidationError("signature and allowed signers must be text")
    if type(namespace) is not str or not namespace:
        raise ValidationError("namespace must be non-empty text")
    if signer is not None and (type(signer) is not str or not signer):
        raise ValidationError("signer must be non-empty text")
    signers = _read_allowed_signers(allowed_signers)
    envelope = _read_sshsig(signature)
    if envelope.namespace != namespace.encode("utf-8"):
        raise IntegrityError(
            f"signature namespace is {_shown(envelope.namespace)}, expected {namespace}"
        )
    principals = sorted(
        {
            principal
            for listed in signers
            if listed.key == envelope.key
            and (listed.namespaces is None or namespace in listed.namespaces)
            for principal in listed.principals
        }
    )
    if not principals:
        raise IntegrityError(f"the signing key is not an allowed signer for {namespace}")
    if signer is not None and signer not in principals:
        raise IntegrityError("the signing key is not allowed for that signer")
    digest = hashlib.new(envelope.hash_algorithm.decode(), data).digest()
    signed = b"SSHSIG" + b"".join(
        _string(part)
        for part in (envelope.namespace, envelope.reserved, envelope.hash_algorithm, digest)
    )
    if not _ed25519_verify(envelope.key, signed, envelope.signature):
        raise IntegrityError("signature does not verify")
    fingerprint = base64.b64encode(hashlib.sha256(envelope.key_blob).digest()).rstrip(b"=")
    return SignatureVerification(
        principals=tuple(principals),
        fingerprint="SHA256:" + fingerprint.decode(),
        hash_algorithm=envelope.hash_algorithm.decode(),
    )
